// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithBaseURL(router, si, "")
}

// Registers handlers, and prepends BaseURL to the paths, so that the paths
// can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.GET(baseURL+"/.well-known/jwks", wrapper.GetJwks)
	router.GET(baseURL+"/.well-known/openid-configuration", wrapper.GetOpenidConfiguration)
	router.DELETE(baseURL+"/internal/orgs/:orgId/deployments", wrapper.InternalDeleteDeployments)
	router.POST(baseURL+"/internal/orgs/:orgId/deployments/:deploymentId/actions/force-failure", wrapper.InternalForceFailDeployment)
	router.POST(baseURL+"/internal/orgs/:orgId/modules/:moduleId/actions/check-usage", wrapper.InternalCheckModuleUsage)
	router.GET(baseURL+"/orgs/:orgId/active-resources", wrapper.ListActiveResourceNodes)
	router.GET(baseURL+"/orgs/:orgId/deployments", wrapper.ListDeployments)
	router.POST(baseURL+"/orgs/:orgId/deployments", wrapper.CreateDeployment)
	router.GET(baseURL+"/orgs/:orgId/deployments/:deploymentId", wrapper.GetDeployment)
	router.POST(baseURL+"/orgs/:orgId/deployments/:deploymentId/actions/diff", wrapper.CalculateDeploymentDiff)
	router.GET(baseURL+"/orgs/:orgId/deployments/:deploymentId/actions/get-logs", wrapper.GetDeploymentLogs)
	router.GET(baseURL+"/orgs/:orgId/deployments/:deploymentId/actions/wait-for-complete", wrapper.WaitForDeploymentComplete)
	router.GET(baseURL+"/orgs/:orgId/deployments/:deploymentId/bundle", wrapper.GetDeploymentBundle)
	router.GET(baseURL+"/orgs/:orgId/deployments/:deploymentId/encrypted-outputs", wrapper.GetDeploymentEncryptedOutputs)
	router.GET(baseURL+"/orgs/:orgId/deployments/:deploymentId/resources", wrapper.ListDeploymentResourceNodes)
	router.POST(baseURL+"/orgs/:orgId/deployments/:deploymentId/results", wrapper.UpdateDeploymentResults)
	router.GET(baseURL+"/orgs/:orgId/deployments/:deploymentId/tf", wrapper.GetDeploymentTf)
	router.GET(baseURL+"/orgs/:orgId/last-deployments", wrapper.ListLastDeployments)
	router.GET(baseURL+"/orgs/:orgId/metadata-keys", wrapper.ListMetadataKeys)
	router.POST(baseURL+"/orgs/:orgId/metadata-keys", wrapper.CreateMetadataKey)
	router.DELETE(baseURL+"/orgs/:orgId/metadata-keys/:metadataKeyName", wrapper.DeleteMetadataKey)
	router.GET(baseURL+"/orgs/:orgId/metadata-keys/:metadataKeyName", wrapper.GetMetadataKey)
	router.PATCH(baseURL+"/orgs/:orgId/metadata-keys/:metadataKeyName", wrapper.UpdateMetadataKey)

}

