// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Show JSON Web Keys Set (JWKS).
	// (GET /.well-known/jwks)
	GetJwks(ctx context.Context, request GetJwksRequestObject) (GetJwksResponseObject, error)
	// Show OIDC discovery configuration.
	// (GET /.well-known/openid-configuration)
	GetOpenidConfiguration(ctx context.Context, request GetOpenidConfigurationRequestObject) (GetOpenidConfigurationResponseObject, error)
	// Delete all the deployments for an project_id, env_id combination. The last deployment must be a successful destroy.
	// (DELETE /internal/orgs/{orgId}/deployments)
	InternalDeleteDeployments(ctx context.Context, request InternalDeleteDeploymentsRequestObject) (InternalDeleteDeploymentsResponseObject, error)
	// Emergency API for force failing a deployment.
	// (POST /internal/orgs/{orgId}/deployments/{deploymentId}/actions/force-failure)
	InternalForceFailDeployment(ctx context.Context, request InternalForceFailDeploymentRequestObject) (InternalForceFailDeploymentResponseObject, error)
	// Check whether a given module is in use in a resource graph.
	// (POST /internal/orgs/{orgId}/modules/{moduleId}/actions/check-usage)
	InternalCheckModuleUsage(ctx context.Context, request InternalCheckModuleUsageRequestObject) (InternalCheckModuleUsageResponseObject, error)
	// List active resource nodes
	// (GET /orgs/{orgId}/active-resources)
	ListActiveResourceNodes(ctx context.Context, request ListActiveResourceNodesRequestObject) (ListActiveResourceNodesResponseObject, error)
	// List deployments in the organization
	// (GET /orgs/{orgId}/deployments)
	ListDeployments(ctx context.Context, request ListDeploymentsRequestObject) (ListDeploymentsResponseObject, error)
	// Create a new deployment in the target project and environment.
	// (POST /orgs/{orgId}/deployments)
	CreateDeployment(ctx context.Context, request CreateDeploymentRequestObject) (CreateDeploymentResponseObject, error)
	// Get a deployment by id in the org
	// (GET /orgs/{orgId}/deployments/{deploymentId})
	GetDeployment(ctx context.Context, request GetDeploymentRequestObject) (GetDeploymentResponseObject, error)
	// Calculate the diff from another deployment to this one.
	// (POST /orgs/{orgId}/deployments/{deploymentId}/actions/diff)
	CalculateDeploymentDiff(ctx context.Context, request CalculateDeploymentDiffRequestObject) (CalculateDeploymentDiffResponseObject, error)
	// Get the logs produced by the runner execution during the deployment.
	// (GET /orgs/{orgId}/deployments/{deploymentId}/actions/get-logs)
	GetDeploymentLogs(ctx context.Context, request GetDeploymentLogsRequestObject) (GetDeploymentLogsResponseObject, error)
	// Long-poll wait for the deployment to be completed. Either a 200 OK is returned indicating that the deployment is complete, or a 408 will indicate that the client must continue waiting.
	// (GET /orgs/{orgId}/deployments/{deploymentId}/actions/wait-for-complete)
	WaitForDeploymentComplete(ctx context.Context, request WaitForDeploymentCompleteRequestObject) (WaitForDeploymentCompleteResponseObject, error)
	// Get a bundle archive for a deployment. This API is called by the runner during execution and is not intended for public consumption.
	// (GET /orgs/{orgId}/deployments/{deploymentId}/bundle)
	GetDeploymentBundle(ctx context.Context, request GetDeploymentBundleRequestObject) (GetDeploymentBundleResponseObject, error)
	// Get the encrypted outputs produced by the deployment.
	// (GET /orgs/{orgId}/deployments/{deploymentId}/encrypted-outputs)
	GetDeploymentEncryptedOutputs(ctx context.Context, request GetDeploymentEncryptedOutputsRequestObject) (GetDeploymentEncryptedOutputsResponseObject, error)
	// List resource nodes for a deployment
	// (GET /orgs/{orgId}/deployments/{deploymentId}/resources)
	ListDeploymentResourceNodes(ctx context.Context, request ListDeploymentResourceNodesRequestObject) (ListDeploymentResourceNodesResponseObject, error)
	// Return the runner outcome for a specific deployment.
	// (POST /orgs/{orgId}/deployments/{deploymentId}/results)
	UpdateDeploymentResults(ctx context.Context, request UpdateDeploymentResultsRequestObject) (UpdateDeploymentResultsResponseObject, error)
	// Returns the compiled TF file associated with a deployment.
	// (GET /orgs/{orgId}/deployments/{deploymentId}/tf)
	GetDeploymentTf(ctx context.Context, request GetDeploymentTfRequestObject) (GetDeploymentTfResponseObject, error)
	// List the last deployment for each project_id and env_id combination
	// (GET /orgs/{orgId}/last-deployments)
	ListLastDeployments(ctx context.Context, request ListLastDeploymentsRequestObject) (ListLastDeploymentsResponseObject, error)
	// List metadata keys for an organization
	// (GET /orgs/{orgId}/metadata-keys)
	ListMetadataKeys(ctx context.Context, request ListMetadataKeysRequestObject) (ListMetadataKeysResponseObject, error)
	// Create a new metadata key for an organization
	// (POST /orgs/{orgId}/metadata-keys)
	CreateMetadataKey(ctx context.Context, request CreateMetadataKeyRequestObject) (CreateMetadataKeyResponseObject, error)
	// Delete a metadata key for an organization
	// (DELETE /orgs/{orgId}/metadata-keys/{metadataKeyName})
	DeleteMetadataKey(ctx context.Context, request DeleteMetadataKeyRequestObject) (DeleteMetadataKeyResponseObject, error)
	// Get a metadata key for an organization
	// (GET /orgs/{orgId}/metadata-keys/{metadataKeyName})
	GetMetadataKey(ctx context.Context, request GetMetadataKeyRequestObject) (GetMetadataKeyResponseObject, error)
	// Update a metadata key for an organization
	// (PATCH /orgs/{orgId}/metadata-keys/{metadataKeyName})
	UpdateMetadataKey(ctx context.Context, request UpdateMetadataKeyRequestObject) (UpdateMetadataKeyResponseObject, error)
}

type StrictHandlerFunc = strictecho.StrictEchoHandlerFunc
type StrictMiddlewareFunc = strictecho.StrictEchoMiddlewareFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

